example.code:
// Pre-built fade animations
element.FadeIn(durationMs: 500);
element.FadeOut(durationMs: 300);

// Slide in from the right
element.SlideIn(durationMs: 400, direction: "right");

// Custom animation using builders
element.Animate(
    new KeyframeBuilder()
        .AddFrame(new { transform = "rotate(0deg)" })
        .AddFrame(new { transform = "rotate(360deg)" }),
    new AnimationOptionsBuilder()
        .Duration(1000)
        .Iterations(double.PositiveInfinity));

// Build options with method chaining
var options = new AnimationOptionsBuilder()
    .Duration(500)
    .Easing(Animations.Easing.EaseInOut)
    .Fill(FillMode.Forwards)
    .Iterations(3)
    .Direction(PlaybackDirection.Alternate)
    .Build();

element.Animate(keyframes, options);

// Implicit conversion -- no need to call Build()
KeyframeAnimationOptions opts = new AnimationOptionsBuilder()
    .Duration(200)
    .Easing(Animations.Easing.EaseOut);

// Use a named easing
var options = new AnimationOptionsBuilder()
    .Duration(500)
    .Easing(Easing.EaseInOut);

// Use a custom cubic-bezier
var bounce = Easing.CubicBezier(0.68, -0.55, 0.27, 1.55);

// Use steps for a sprite animation
var sprite = Easing.Steps(8, "end");

var keyframes = new KeyframeBuilder()
    .AddFrame(new { opacity = 0, transform = "scale(0.5)" })
    .AddFrame(new { opacity = 1, transform = "scale(1)" }, offset: 0.6)
    .AddFrame(new { opacity = 1, transform = "scale(1.1)" }, easing: Easing.EaseOut)
    .Build();

element.Animate(keyframes, 500);

using (ctx.SaveState()) {
    ctx.GlobalAlpha = 0.5;
    ctx.FillRect(0, 0, 100, 100);
}
// GlobalAlpha is restored to its previous value here.

var gradient = ctx.LinearGradient(0, 0, 200, 0)
    .AddStop(0, CssColor.Named("red"))
    .AddStop(1, CssColor.Named("blue"))
    .Build();
ctx.SetFill(gradient).FillRect(0, 0, 200, 100);

// Basic font
var font = CanvasFont.Of(16, "Arial");
ctx.Font = font; // "16px Arial"

// Styled font
var boldItalic = CanvasFont.Of(24, "Georgia").Bold().Italic();
ctx.Font = boldItalic; // "italic bold 24px Georgia"

// Custom weight
var light = CanvasFont.Of(14, "Roboto").WithWeight("300");
ctx.Font = light; // "300 14px Roboto"

var ctx = canvas.GetContext2D();

using (ctx.SaveState()) {
    ctx.Translate(50, 50);
    ctx.Rotate(Math.PI / 4);
    ctx.FillRect(0, 0, 100, 100);
}
// Context state is automatically restored here -- translation and rotation are undone.

// Linear gradient from red to blue
var gradient = ctx.LinearGradient(0, 0, 200, 0)
    .AddStop(0, CssColor.Named("red"))
    .AddStop(0.5, CssColor.Named("white"))
    .AddStop(1, CssColor.Named("blue"))
    .Build();

ctx.SetFill(gradient).FillRect(0, 0, 200, 100);

// Implicit conversion -- no need to call Build()
CanvasGradient g = ctx.RadialGradient(100, 100, 0, 100, 100, 80)
    .AddStop(0, "yellow")
    .AddStop(1, "green");

// Draw a triangle
ctx.Path()
   .MoveTo(150, 50)
   .LineTo(250, 200)
   .LineTo(50, 200)
   .ClosePath()
   .Stroke();

// Draw a rounded rectangle and fill it
ctx.Path()
   .RoundRect(10, 10, 180, 80, 15)
   .Fill();

// In a Blazor WebAssembly app:
JsObject.Backend = new JSInteropBackend(jsRuntime);

// In a unit test:
JsObject.Backend = new FakeBrowserBackend();

public readonly struct Length : ICssValue {
    private readonly double _value;
    private readonly string _unit;

    public string ToCss() => $"{_value}{_unit}";
}

// Usage:
Assert.Equal("1.5rem", Length.Rem(1.5).ToCss());

public record class RequestInit : IWebIdlSerializable {
    public string? Method { get; set; }
    public string? Body { get; set; }

    public object ToJs() => new { method = Method, body = Body };
}

// Using the static RunAsync helper:
await JsBatch.RunAsync(batch => {
    batch.SetProperty(element, "textContent", "Hello");
    batch.SetProperty(element, "className", "active");
    batch.InvokeVoid(element, "focus");
});

// Using an instance directly:
var batch = new JsBatch();
batch.SetProperty(elementA, "hidden", true);
batch.SetProperty(elementB, "hidden", false);
await batch.ExecuteAsync();

await JsBatch.RunAsync(batch => {
    batch.SetProperty(element, "textContent", "Updated");
    batch.InvokeVoid(element, "scrollIntoView");
});

await element.BatchAsync(scope => scope
    .Set("textContent", "Hello")
    .Set("className", "highlight")
    .Call("scrollIntoView")
);

public partial class Document : JsObject {
    [JsName("getElementById")]
    public Element? GetElementById(string elementId) { ... }

    [JsName("innerHTML")]
    public string InnerHtml { get; set; }
}

// Generated code (simplified):
public partial class Document : JsObject {
    public Element? GetElementById(string id) =>
        Invoke<Element?>("getElementById", id);

    public string Title {
        get => GetProperty<string>("title");
        set => SetProperty("title", value);
    }
}

// Usage:
JsObject.Backend = new JSInteropBackend(jsRuntime);
var doc = new Document { Handle = backend.GetGlobal("document") };
doc.Title = "Hello, BrowserApi!";

await element.BatchAsync(scope => scope
    .Set("textContent", "Hello, world!")
    .Set("className", "active")
    .Call("focus")
);
// All three operations are sent to JavaScript in a single interop call.

