member.typeparam:
The event type to deserialize from the DOM event (e.g., ,
). Must derive from  and have a
parameterless constructor.

example.code:
// Subscribe to clicks, then unsubscribe when done
using var subscription = button.OnClick(e => Console.WriteLine("Clicked!"));

// Or manually dispose later
var sub = button.OnClick(e => HandleClick(e));
// ... some time later ...
sub.Dispose(); // removes the event listener

// Check if the Enter key was pressed
if (keyboardEvent.IsKey(Key.Enter)) { /* handle enter */ }

// Get the string value
string value = Key.ArrowUp.ToStringValue(); // "ArrowUp"

Modifiers mods = keyboardEvent.GetModifiers();
if (mods == (Modifiers.Ctrl | Modifiers.Shift))
{
    // Exactly Ctrl+Shift (no other modifiers)
}

if (keyboardEvent.HasModifier(Modifiers.Ctrl))
{
    // Ctrl is held (possibly with other modifiers too)
}

member.returns:
 if the event's key property matches the
 of the specified  member;
otherwise, .

example.code:
if (keyboardEvent.IsKey(Key.Enter))
{
    // The Enter key was pressed
}

member.returns:
 if the event's code property matches the
 of the specified  member;
otherwise, .

example.code:
// WASD movement (works on QWERTY, AZERTY, Dvorak, etc.)
if (keyboardEvent.IsCode(KeyCode.KeyW)) { /* move forward */ }
if (keyboardEvent.IsCode(KeyCode.KeyA)) { /* move left */ }
if (keyboardEvent.IsCode(KeyCode.KeyS)) { /* move backward */ }
if (keyboardEvent.IsCode(KeyCode.KeyD)) { /* move right */ }

// Check if the physical "W" key was pressed (for WASD controls, works on any layout)
if (keyboardEvent.IsCode(KeyCode.KeyW)) { /* move forward */ }

// Get the string value
string code = KeyCode.ArrowUp.ToStringValue(); // "ArrowUp"

// Check for Ctrl+Shift combination
Modifiers mods = keyboardEvent.GetModifiers();
if ((mods & (Modifiers.Ctrl | Modifiers.Shift)) == (Modifiers.Ctrl | Modifiers.Shift))
{
    // Both Ctrl and Shift are held
}

// Use HasModifier extension for simpler checks
if (keyboardEvent.HasModifier(Modifiers.Ctrl))
{
    // Ctrl is held (possibly with other modifiers)
}

MouseButton button = mouseEvent.GetButton();
if (button == MouseButton.Left)
{
    // Primary (left) button was clicked
}

// Check if the left button is currently held during a mousemove event
if (mouseEvent.HasButton(MouseButtons.Left))
{
    // User is dragging with the left button
}

// Check for multiple buttons
MouseButtons buttons = mouseEvent.GetButtons();
if ((buttons & MouseButtons.Left) != 0 && (buttons & MouseButtons.Right) != 0)
{
    // Both left and right buttons are pressed simultaneously
}

// Check for Ctrl+Click
if (mouseEvent.GetModifiers() == Modifiers.Ctrl)
{
    // Ctrl was the only modifier held during the click
}

if (mouseEvent.GetButton() == MouseButton.Right)
{
    // Right-click detected
}

// Detect dragging with the left button during mousemove
if (mouseEvent.HasButton(MouseButtons.Left))
{
    // User is dragging with the left button held
}

PointerType? type = pointerEvent.GetPointerType();
switch (type)
{
    case PointerType.Mouse:
        // Handle mouse input
        break;
    case PointerType.Touch:
        // Handle touch input (e.g., larger hit targets)
        break;
    case PointerType.Pen:
        // Handle pen/stylus input (e.g., pressure sensitivity)
        break;
    case null:
        // Unknown pointer type
        break;
}

