var result = await Http.Get("/api/data").TrySendAsync();
if (result.IsSuccess)
    Console.WriteLine($"Status: {result.Response!.Status}");
else
    Console.WriteLine($"Error: {result.Error!.Message}");

var result = await Http.Get("/api/users/42").TrySendAsync<User>();
