remarks.para:
 mirrors the browser Fetch API with a fluent, strongly-typed C# surface.
Each method creates a  pre-configured with the URL and HTTP method;
from there you can add headers, set a body, configure CORS mode, and finally send the request.

example.code:
// Simple GET and deserialize
var user = await Http.GetAsync<User>("/api/users/42");

// POST with JSON body and custom headers
var created = await Http.Post("/api/users")
    .WithJsonBody(new { Name = "Alice", Email = "alice@example.com" })
    .WithHeader("Authorization", "Bearer token123")
    .SendJsonAsync<User>();

// Non-throwing pattern
var result = await Http.Get("/api/data").TrySendAsync();
if (result.IsSuccess)
    Console.WriteLine(result.Response!.Status);

// POST with JSON body
var user = await Http.Post("/api/users")
    .WithJsonBody(new { Name = "Alice" })
    .WithHeader("Authorization", "Bearer token")
    .SendJsonAsync<User>();

// GET with abort signal
var controller = new AbortController();
var response = await Http.Get("/api/stream")
    .WithSignal(controller.Signal)
    .SendAsync();

var response = await Http.Get("/api/data")
    .WithHeaders(
        ("Accept", "application/json"),
        ("X-Custom", "value"))
    .SendAsync();

var response = await Http.Get("/api/users/1").SendAsync();
var user = await response.JsonAsync<User>();
Console.WriteLine(user.Name);

var response = await Http.Get("/api/data").SendAsync();
response.EnsureSuccess(); // throws if status is 4xx or 5xx
var text = await response.TextAsync();

// Typed localStorage
var storage = window.TypedLocalStorage();
storage.Set("prefs", new UserPrefs { Theme = "dark", FontSize = 14 });
var prefs = storage.Get<UserPrefs>("prefs");

// Listen for cross-tab changes
window.OnStorageChanged(args => {
    Console.WriteLine($"Key '{args.Key}' changed from '{args.OldValue}' to '{args.NewValue}'");
});

var storage = window.TypedLocalStorage();

// Store and retrieve typed objects
storage.Set("settings", new AppSettings { Theme = "dark", Lang = "en" });
var settings = storage.Get<AppSettings>("settings");

// Simple key-value checks
if (storage.ContainsKey("settings"))
    Console.WriteLine($"Storage has {storage.Count} items");

// Enumerate all keys
foreach (var key in storage.Keys)
    Console.WriteLine(key);

// Remove or clear
storage.Remove("settings");
storage.Clear();
